contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public payable {
        require(_feeRate <= 5000, "fee rate above max");

        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        address baseTokenAfter = c.baseToken();
        bool initializedAfter = c.initialized();

        bool reverted;
        try c.initialize(
            address(0xdead),
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(baseTokenAfter == _baseToken && initializedAfter && reverted);
    }

    receive() external payable {}
}

